import React, { useEffect, useState, useRef } from 'react';
import Chart from 'chart.js/auto';
import Select from 'react-select';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [aircrafts, setAircrafts] = useState([]);
    const [selectedAircrafts, setSelectedAircrafts] = useState([]);
    const [years, setYears] = useState([]);
    const [selectedYears, setSelectedYears] = useState([]);
    const [months, setMonths] = useState([
        { value: 0, label: 'January' },
        { value: 1, label: 'February' },
        { value: 2, label: 'March' },
        { value: 3, label: 'April' },
        { value: 4, label: 'May' },
        { value: 5, label: 'June' },
        { value: 6, label: 'July' },
        { value: 7, label: 'August' },
        { value: 8, label: 'September' },
        { value: 9, label: 'October' },
        { value: 10, label: 'November' },
        { value: 11, label: 'December' },
    ]);
    const [selectedMonths, setSelectedMonths] = useState([]);
    const chartRef = useRef(null);

    const parseDate = (dateString) => {
        const [month, day, year] = dateString.split('/');
        return new Date(2000 + parseInt(year), parseInt(month) - 1, parseInt(day));
    };

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Fetched Data:', result);
                setData(result);

                // Extract unique aircrafts and years
                const invoices = result.Invoices?.items || [];
                const uniqueAircrafts = Array.from(new Set(invoices.map(invoice => invoice.Aircraft)));
                setAircrafts(uniqueAircrafts.map(aircraft => ({ value: aircraft, label: aircraft })));

                const uniqueYears = Array.from(new Set(invoices.map(invoice => {
                    const date = parseDate(invoice['Trip start Z']);
                    return date.getFullYear();
                }))).filter(year => !isNaN(year));
                setYears(uniqueYears.sort((a, b) => a - b).map(year => ({ value: year, label: year.toString() })));

            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        const invoices = data.Invoices?.items || [];
        const loggedFlights = data['Logged-Flights']?.items || [];

        // Filter invoices with status "Invoiced"
        let filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced');

        if (selectedAircrafts.length > 0) {
            const selectedAircraftValues = selectedAircrafts.map(aircraft => aircraft.value);
            filteredInvoices = filteredInvoices.filter(invoice => selectedAircraftValues.includes(invoice.Aircraft));
        }

        if (selectedYears.length > 0 || selectedMonths.length > 0) {
            filteredInvoices = filteredInvoices.filter(invoice => {
                const date = parseDate(invoice['Trip start Z']);
                const year = date.getFullYear();
                const month = date.getMonth();

                const yearMatch = selectedYears.length === 0 || selectedYears.some(y => y.value === year);
                const monthMatch = selectedMonths.length === 0 || selectedMonths.some(m => m.value === month);

                return yearMatch && monthMatch;
            });
        }

        const revenuePerHour = {};

        filteredInvoices.forEach(invoice => {
            const trip = invoice.Trip;
            const aircraft = invoice.Aircraft;
            const price = parseFloat(invoice.Price);

            // Get the flights matching the trip and aircraft
            const flights = loggedFlights.filter(flight => flight.Trip === trip && flight.Aircraft === aircraft);
            const totalFlightHours = flights.reduce((sum, flight) => sum + parseFloat(flight['Flight hrs']), 0);

            if (!revenuePerHour[aircraft]) {
                revenuePerHour[aircraft] = { totalPrice: 0, totalFlightHours: 0 };
            }

            revenuePerHour[aircraft].totalPrice += price;
            revenuePerHour[aircraft].totalFlightHours += totalFlightHours;
        });

        console.log('Revenue per Hour:', revenuePerHour);

        const labels = Object.keys(revenuePerHour);
        const dataPoints = labels.map(aircraft => {
            const { totalPrice, totalFlightHours } = revenuePerHour[aircraft];
            return (totalFlightHours > 0) ? (totalPrice / totalFlightHours).toFixed(2) : 0;
        });

        console.log('Chart Labels:', labels);
        console.log('Chart Data Points:', dataPoints);

        const ctx = document.getElementById('myChart').getContext('2d');

        // Destroy the previous chart instance if it exists
        if (chartRef.current) {
            chartRef.current.destroy();
        }

        // Create a new chart instance and save it to the ref
        chartRef.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [{
                    label: 'Revenue per Hour',
                    data: dataPoints,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

    }, [data, selectedAircrafts, selectedYears, selectedMonths]);

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div style={{ width: '80%', margin: 'auto' }}>
            <h1>Revenue per Hour of Aircrafts</h1>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                <Select
                    isMulti
                    options={aircrafts}
                    value={selectedAircrafts}
                    onChange={setSelectedAircrafts}
                    placeholder="Select Aircrafts"
                    styles={{ container: (provided) => ({ ...provided, width: '30%' }) }}
                />
                <Select
                    isMulti
                    options={years}
                    value={selectedYears}
                    onChange={setSelectedYears}
                    placeholder="Select Years"
                    styles={{ container: (provided) => ({ ...provided, width: '30%' }) }}
                />
                <Select
                    isMulti
                    options={months}
                    value={selectedMonths}
                    onChange={setSelectedMonths}
                    placeholder="Select Months"
                    styles={{ container: (provided) => ({ ...provided, width: '30%' }) }}
                />
            </div>
            <div style={{ height: '500px' }}>
                <canvas id="myChart"></canvas>
            </div>
        </div>
    );
};

export default ChartComponent;
